  --control-placeholder: oklch(0.55 0.055 220);
  --control-hover-border: oklch(0.86 0.18 192 / 0.74);
  --focus-ring: oklch(0.82 0.15 195 / 0.2);
  --record-surface: oklch(0.2 0.06 275 / 0.6);
  --switch-off: oklch(0.34 0.055 275);
  --switch-shadow: oklch(0.03 0.02 285 / 0.66);
  --count-surface: oklch(0.72 0.22 330 / 0.14);
  --selected-surface: oklch(0.82 0.15 195 / 0.13);
  --approval-color: oklch(0.78 0.19 330 / 0.86);
  --action-border: oklch(0.78 0.15 195 / 0.25);
  --action-shadow: 0 -14px 32px oklch(0.035 0.025 285 / 0.52);
  --secondary-border: oklch(0.77 0.18 330 / 0.46);
  --secondary-text: oklch(0.85 0.12 330);
  --button-border: oklch(0.87 0.18 192 / 0.94);
  --button-inset: oklch(0.98 0.03 205 / 0.22);
  --button-shadow: oklch(0.71 0.18 195 / 0.34);
  --button-text: oklch(0.12 0.045 282);
  --legal-text: oklch(0.56 0.06 220);
  border-radius: 6px;
  color-scheme: dark;
  font-family: 'IBM Plex Mono', 'Cascadia Mono', 'Microsoft YaHei', monospace;
}

.masthead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 24px 24px 20px;
}

.registry-no,
.chapter-heading p,
.section-heading span,
.character-record header span,
.legal-note {
  margin: 0;
  font-family: var(--mono-font);
  font-size: 12px;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.registry-no {
  color: var(--brass);
  letter-spacing: 0.12em;
}

.masthead h1 {
  margin: 7px 0 3px;
  font-size: 30px;
  font-weight: 800;
  letter-spacing: 0.16em;
  line-height: 1.05;
}

.masthead-subtitle {
  margin: 0;
  color: var(--shell-muted);
  font-family: var(--ui-font);
  font-size: 15px;
  font-weight: 500;
  line-height: 1.6;
  letter-spacing: 0.03em;
}

.masthead-seal {
  display: grid;
  flex: 0 0 58px;
  place-items: center;
  aspect-ratio: 1;
  border: 1px solid var(--seal-border);
  color: var(--seal-color);
  transform: rotate(3deg);
  transition:
    border-color 180ms cubic-bezier(0.16, 1, 0.3, 1),
    color 180ms cubic-bezier(0.16, 1, 0.3, 1),
    transform 180ms cubic-bezier(0.16, 1, 0.3, 1);
}

.masthead-seal span {
  margin-top: -7px;
  font-family: var(--ui-font);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.theme-dock {
  display: grid;
  gap: 12px;
  padding: 0 20px 20px;
}

.theme-dock-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  color: var(--shell-muted);
  font-family: var(--ui-font);
}

.theme-dock-heading > div {
  display: flex;
  min-width: 0;
  align-items: baseline;
  gap: 9px;
}

.theme-dock-heading span {
  color: var(--shell-ink);
  font-size: 13px;
  font-weight: 750;
  letter-spacing: 0.04em;
}

.theme-dock-heading small {
  overflow: hidden;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.5;
  letter-spacing: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theme-dock-heading > strong {
  color: var(--brass);
  font-size: 12px;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

.theme-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--theme-border);
  border-radius: 8px;
  background: var(--theme-panel);
}

.theme-option {
  position: relative;
  display: grid;
  min-width: 0;
  min-height: 90px;
  grid-template-columns: 34px minmax(0, 1fr) 16px;
  align-items: center;
  gap: 12px;
  border: 0;
  border-right: 1px solid var(--theme-border);
  border-bottom: 1px solid var(--theme-border);
  background: transparent;
  color: var(--shell-muted);
  padding: 12px 14px;
  text-align: left;
  cursor: pointer;
  transition:
    background-color 180ms cubic-bezier(0.16, 1, 0.3, 1),
    color 180ms cubic-bezier(0.16, 1, 0.3, 1);
}

.theme-option:nth-child(2n) {
  border-right: 0;
}

.theme-option:nth-last-child(-n + 2) {
  border-bottom: 0;
}

.theme-option:hover {
  background: var(--theme-hover);
  color: var(--shell-ink);
}

.theme-option:focus-visible {
  z-index: 1;
  outline: 2px solid var(--cinnabar-active);
  outline-offset: -3px;
}

.theme-option.active {
  background: var(--selected-surface);
  color: var(--shell-ink);
}

.theme-glyph {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: var(--brass);
}

.theme-option-copy {
  display: grid;
  min-width: 0;
  gap: 5px;
  font-family: var(--ui-font);
}

.theme-option-copy strong,
.theme-option-copy small {
  overflow: hidden;
}

.theme-option-copy strong {
  color: inherit;
  font-size: 14px;
  font-weight: 750;
  line-height: 1.35;
  letter-spacing: 0.02em;
}

.theme-option-copy small {
  display: -webkit-box;
  color: var(--shell-muted);
  font-size: 13px;
  font-weight: 500;
  line-height: 1.55;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.theme-check {
  color: var(--cinnabar-active);
}

.world-forge[data-theme='astrolabe'] .masthead-seal {
  position: relative;
  border-radius: 50%;
  box-shadow: 0 0 24px oklch(0.75 0.11 76 / 0.16);
  transform: none;
}

.world-forge[data-theme='astrolabe'] .masthead-seal::before {
  position: absolute;
  inset: -7px;
  border: 1px solid oklch(0.74 0.1 75 / 0.28);
  border-radius: 50%;
  content: '';
  transform: rotate(24deg) scaleX(0.76);
}

.world-forge[data-theme='astrolabe'] .theme-options,
.world-forge[data-theme='astrolabe'] .dossier {
  border-radius: 14px;
}

.world-forge[data-theme='astrolabe'] .control,
.world-forge[data-theme='astrolabe'] .button,
.world-forge[data-theme='astrolabe'] .rule-tab,
.world-forge[data-theme='astrolabe'] .add-record,
.world-forge[data-theme='astrolabe'] .character-record {
  border-radius: 9px;
}

.world-forge[data-theme='astrolabe'] .paper-notch {
  top: -6px;
  width: 12px;
  height: 12px;
  background: var(--cinnabar);
  clip-path: none;
  transform: translateX(-50%) rotate(45deg);
}

.world-forge[data-theme='terminal'] .masthead-seal {
  border-width: 2px;
  border-radius: 2px;
  transform: none;
}

.world-forge[data-theme='terminal'] .masthead h1,
.world-forge[data-theme='terminal'] .chapter-heading h2 {
  font-family: 'IBM Plex Mono', 'Cascadia Mono', 'Microsoft YaHei', monospace;
  letter-spacing: 0.08em;
}

.world-forge[data-theme='terminal'] .theme-options,
.world-forge[data-theme='terminal'] .dossier,
.world-forge[data-theme='terminal'] .control,
.world-forge[data-theme='terminal'] .button,
.world-forge[data-theme='terminal'] .rule-tab,
.world-forge[data-theme='terminal'] .add-record,
.world-forge[data-theme='terminal'] .character-record {
  border-radius: 0;
}

.world-forge[data-theme='terminal'] .theme-glyph,
.world-forge[data-theme='terminal'] .chapter-icon,
.world-forge[data-theme='terminal'] .section-icon,
.world-forge[data-theme='terminal'] .icon-button {
  border-radius: 3px;
}

.world-forge[data-theme='terminal'] .dossier {
  background-size: 24px 24px;
}

.world-forge[data-theme='terminal'] .paper-notch {
  top: 0;
  width: 34px;
  height: 5px;
  background: var(--cinnabar);
  clip-path: none;
}

.world-forge[data-theme='terminal'] .approval-mark {
  width: 112px;
  height: 72px;
  border: 2px solid currentColor;
  border-radius: 0;
  transform: none;
}

.world-forge[data-theme='terminal'] .approval-mark::after {
  border-radius: 0;
}

.world-forge[data-theme='neon'] .masthead-seal {
  border-width: 2px;
  border-radius: 0;
  background: oklch(0.16 0.06 278 / 0.84);
  box-shadow:
    inset 0 0 14px oklch(0.82 0.15 195 / 0.14),
    0 0 18px oklch(0.72 0.22 330 / 0.24);
  clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
  transform: none;
}

.world-forge[data-theme='neon'] .masthead h1,
.world-forge[data-theme='neon'] .chapter-heading h2 {
  font-family: 'IBM Plex Mono', 'Cascadia Mono', 'Microsoft YaHei', monospace;
  text-shadow: 0 0 18px oklch(0.82 0.15 195 / 0.18);
}

.world-forge[data-theme='neon'] .theme-options,
.world-forge[data-theme='neon'] .dossier,
.world-forge[data-theme='neon'] .control,
.world-forge[data-theme='neon'] .button,
.world-forge[data-theme='neon'] .rule-tab,
.world-forge[data-theme='neon'] .add-record,
.world-forge[data-theme='neon'] .character-record {
  border-radius: 3px;
}

.world-forge[data-theme='neon'] .theme-glyph,
.world-forge[data-theme='neon'] .chapter-icon,
.world-forge[data-theme='neon'] .section-icon,
.world-forge[data-theme='neon'] .icon-button {
  border-radius: 2px;
  box-shadow: 0 0 12px oklch(0.82 0.15 195 / 0.12);
}

.world-forge[data-theme='neon'] .dossier {
  background-size: 28px 28px;
}

.world-forge[data-theme='neon'] .paper-notch {
  top: 0;
  width: 72px;
  height: 3px;
  background: linear-gradient(90deg, var(--brass) 0 28%, var(--cinnabar) 28% 100%);
  box-shadow: 0 0 12px var(--cinnabar);
  clip-path: none;
}

.world-forge[data-theme='neon'] .theme-option.active {
  box-shadow: inset 3px 0 0 var(--cinnabar);
}

.world-forge[data-theme='neon'] .approval-mark {
  width: 118px;
  height: 76px;
  border: 2px solid currentColor;
  border-radius: 0;
  box-shadow: 0 0 18px oklch(0.72 0.22 330 / 0.2);
  clip-path: polygon(9px 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%, 0 9px);
  transform: none;
}

.world-forge[data-theme='neon'] .approval-mark::after {
  border-radius: 0;
}

.chapter-strip {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  padding: 0 20px 18px;
}

.chapter-tab {
  position: relative;
  display: flex;
  min-width: 0;
  min-height: 70px;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: 0;
  border-bottom: 1px solid var(--tab-line);
  background: transparent;
  color: var(--tab-muted);
  text-align: left;
  cursor: pointer;
  transition:
    color 180ms cubic-bezier(0.16, 1, 0.3, 1),
    background-color 180ms cubic-bezier(0.16, 1, 0.3, 1);
}

.chapter-tab::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 2px;
  background: transparent;
  content: '';
  transition: background-color 180ms ease-out;
}

.chapter-tab:not(:disabled):hover {
  background: var(--tab-hover);
  color: var(--shell-ink);
}
.chapter-tab:disabled {
  cursor: default;
  opacity: 0.72;
}
.chapter-tab.active {
  color: var(--shell-ink);
}
.chapter-tab.active::after {
  background: var(--cinnabar-active);
}
.chapter-tab.complete {
  color: var(--tab-complete);
}

.chapter-icon {
  display: grid;
  flex: 0 0 32px;
  width: 32px;
  height: 32px;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
}

.chapter-copy {
  display: grid;
  min-width: 0;
  gap: 3px;
  font-family: var(--ui-font);
}
.chapter-copy small {
  font:
    12px/1.3 'IBM Plex Mono',
    'Cascadia Mono',
    sans-serif;
  letter-spacing: 0.05em;
}
.chapter-copy strong {
  overflow: hidden;
  font-size: 14px;
  font-weight: 720;
  line-height: 1.3;
  letter-spacing: 0.04em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dossier {
  position: relative;
  margin: 0 12px;
  background: var(--dossier-background);
  background-size: auto;
  box-shadow: var(--dossier-shadow);
  color: var(--ink);
  transition:
    background-color 220ms cubic-bezier(0.16, 1, 0.3, 1),
    box-shadow 220ms cubic-bezier(0.16, 1, 0.3, 1),
    color 220ms cubic-bezier(0.16, 1, 0.3, 1);
}

.paper-notch {
  position: absolute;
  top: 0;
  left: 50%;
  width: 26px;
  height: 9px;
  background: var(--canvas);
  clip-path: polygon(0 0, 100% 0, 64% 100%, 36% 100%);
  transform: translateX(-50%);
}

.chapter-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  padding: 34px 28px 22px;
  border-bottom: 1px solid var(--line-strong);
}

.chapter-heading p {
  color: var(--cinnabar);
}
.chapter-heading h2 {
  margin: 7px 0 0;
  font-size: 30px;
  font-weight: 850;
  letter-spacing: 0.12em;
  line-height: 1.15;
}
.chapter-folio {
  color: var(--ink-muted);
  font:
    700 12px/1 'IBM Plex Mono',
    'Cascadia Mono',
    monospace;
  letter-spacing: 0.12em;
}

.chapter-body {
  padding: 0 28px 34px;
  animation: page-forward 240ms cubic-bezier(0.16, 1, 0.3, 1);
}
.chapter-body.step-back {
  animation-name: page-back;
}

@keyframes page-forward {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes page-back {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.chapter-lead {
  max-width: 62ch;
  margin: 0;
  padding: 18px 0 22px;
  color: var(--ink-muted);
  font-size: 13px;
  line-height: 1.8;
}

.dossier-section {
  padding: 26px 0 28px;
  border-top: 1px solid var(--line);
}
.chapter-lead + .dossier-section {
  padding-top: 4px;
  border-top: 0;
}

.section-heading {
  display: grid;
  grid-template-columns: 36px 1fr;
  align-items: center;
  gap: 10px;
  margin-bottom: 20px;
}

.section-heading-actions {
  grid-template-columns: 36px 1fr auto;
}
.section-icon {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border: 1px solid var(--seal-border);
  border-radius: 50%;
  color: var(--cinnabar);
}
.section-heading div > span {
  color: var(--cinnabar);
}
.section-heading h3 {
  margin: 3px 0 0;
  font-size: 19px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.form-grid {
  display: grid;
  gap: 0 16px;
}
.two-col {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.compact-grid {
  grid-template-columns: 1.3fr 0.7fr 0.7fr;
}

.field {
  display: grid;
  gap: 7px;
  margin-bottom: 16px;
}
.field-label {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--ink);
  font-family: 'Noto Sans SC', 'Microsoft YaHei', sans-serif;
  font-size: 12px;
  font-weight: 720;
  letter-spacing: 0.04em;
}
.field-label em {
  color: var(--ink-faint);
  font-size: 12px;
  font-style: normal;
  font-weight: 500;
  line-height: 1.4;
}

.control {
  width: 100%;
  min-height: 48px;
  border: 1px solid var(--line-strong);
  border-radius: 5px;
  outline: none;
  background: var(--control-surface);
  color: var(--ink);
  font:
    500 14px/1.55 'Noto Sans SC',
    'Microsoft YaHei',
    sans-serif;
  padding: 11px 12px;
  transition:
    border-color 160ms ease-out,
    box-shadow 160ms ease-out,
    background-color 160ms ease-out;
}

textarea.control {
  min-height: 82px;
  resize: vertical;
}
.control::placeholder {
  color: var(--control-placeholder);
}
.control:hover {
  border-color: var(--control-hover-border);
  background: var(--paper-soft);
}
.control:focus-visible {
  border-color: var(--cinnabar);
  background: var(--paper-soft);
  box-shadow: 0 0 0 3px var(--focus-ring);
}

.select-wrap {
  position: relative;
  display: block;
}
.select-wrap::after {
  position: absolute;
  top: 50%;
  right: 14px;
  width: 7px;
  height: 7px;
  border-right: 1.5px solid var(--ink-muted);
  border-bottom: 1.5px solid var(--ink-muted);
  content: '';
  pointer-events: none;
  transform: translateY(-70%) rotate(45deg);
}
.select-wrap select {
  appearance: none;
  padding-right: 36px;
}

.text-action,
.receipt-group button {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 0;
  background: transparent;
  color: var(--cinnabar);
  font:
    700 12px/1 'Noto Sans SC',
    'Microsoft YaHei',
    sans-serif;
  cursor: pointer;
}

.text-action:hover,
.receipt-group button:hover {
  color: var(--cinnabar-active);
}

.empty-record {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 14px;
  padding: 18px;
  border: 1px dashed var(--line-strong);
  color: var(--ink-muted);
}

.empty-record strong {
  color: var(--ink);
  font-size: 13px;
}
.empty-record p {
  margin: 4px 0 0;
  font-size: 12px;
  line-height: 1.5;
}
.empty-record button {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--line-strong);
  border-radius: 4px;
  background: transparent;
  color: var(--ink);
  font:
    700 12px/1 'Noto Sans SC',
    sans-serif;
  padding: 0 12px;
  cursor: pointer;
}

.character-record {
  margin-top: 14px;
  padding: 16px;
  border: 1px solid var(--line-strong);
  background: var(--record-surface);
}
.character-record > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}
.character-record header div {
  display: grid;
  gap: 3px;
}
.character-record header span {
  color: var(--cinnabar);
}
.character-record header strong {
  font-size: 14px;
  letter-spacing: 0.06em;
}

.icon-button {
  display: grid;
  flex: 0 0 40px;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 50%;
  background: transparent;
  color: var(--ink-muted);
  cursor: pointer;
}
.icon-button:hover {
  border-color: currentColor;
}
.icon-button.danger:hover {
  color: var(--cinnabar);
}

.tone-list {
  display: grid;
  gap: 6px;
}
.tone-row {
  display: grid;
  grid-template-columns: minmax(120px, 0.9fr) minmax(140px, 1.4fr) 44px;
  align-items: center;
  gap: 14px;
  min-height: 62px;
  border-bottom: 1px solid var(--line);
}
.tone-row > span {
  display: grid;
  gap: 3px;
}
.tone-row strong,
.switch-row strong {
  font-family: 'Noto Sans SC', 'Microsoft YaHei', sans-serif;
  font-size: 13px;
}
.tone-row small,
.switch-row small {
  color: var(--ink-muted);
  font-family: 'Noto Sans SC', 'Microsoft YaHei', sans-serif;
  font-size: 12px;
  line-height: 1.5;
}
.tone-row input {
  width: 100%;
  accent-color: var(--cinnabar);
  cursor: pointer;
}
.tone-row output {
  color: var(--cinnabar);
  font:
    750 14px/1 'IBM Plex Mono',
    'Cascadia Mono',
    monospace;
  text-align: right;
}

.switch-row {
  display: flex;
  min-height: 62px;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 12px;
  padding: 8px 0;
  cursor: pointer;
}
.switch-row > span {
  display: grid;
  gap: 4px;
}
.switch-row input {
  position: relative;
  width: 46px;
  height: 26px;
  flex: 0 0 46px;
  appearance: none;
  border: 1px solid var(--line-strong);
  border-radius: 99px;
  background: var(--switch-off);
  cursor: pointer;
  transition: background-color 160ms ease-out;
}
.switch-row input::after {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--paper-soft);
